css:
/* Hero slider. Each slide is a full-width banner image that carries its own dark
   fade where the copy sits (left); the copy sits on the page grid over it. Without
   script (and on the Design canvas) every slide is in flow, one under the other. */
[data-bz-section="hero-slider"] > .bz-container { padding: 0; }
[data-bz-section="hero-slider"] [data-bz-part~="slide"] {
  position: relative;
  min-height: clamp(460px, 41.5vw, 800px);
  background: var(--ink-dark);
  overflow: hidden;
}
[data-bz-section="hero-slider"] [data-bz-part~="slide"] > .bz-col:first-child {
  position: relative;
  z-index: 2;
  grid-column: 1 / span 6;
  padding: 56px 0 58px max(16px, calc((100vw - var(--container)) / 2 + 16px));
}
[data-bz-section="hero-slider"] [data-bz-part~="slide"] > .bz-col:last-child {
  position: absolute;
  inset: 0;
  width: 100%;
}
[data-bz-section="hero-slider"] [data-bz-part~="slide"] > .bz-col:last-child .bz-block,
[data-bz-section="hero-slider"] [data-bz-part~="slide"] > .bz-col:last-child .bz-container,
[data-bz-section="hero-slider"] [data-bz-part~="slide"] > .bz-col:last-child figure,
[data-bz-section="hero-slider"] [data-bz-part~="slide"] > .bz-col:last-child a { display: block; height: 100%; margin: 0; padding: 0; }
[data-bz-section="hero-slider"] [data-bz-part~="slide"] img {
  display: block;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  object-position: right center;
  border-radius: 0;
}
[data-bz-section="hero-slider"] h1 {
  margin: 0 0 8px;
  white-space: pre-line;
  font: 700 clamp(2.25rem, 3.458vw, 5rem) / 1 var(--font-heading);
  letter-spacing: 0;
  color: var(--accent);
}
[data-bz-section="hero-slider"] h1::first-line { color: #fff; }
[data-bz-section="hero-slider"] .bz-text p {
  margin: 0;
  font: 400 clamp(0.9375rem, 1.09vw, 1.4rem) / 1.3 var(--font-body);
  white-space: pre-line;
  color: #fff;
}
[data-bz-section="hero-slider"] [data-bz-part~="dots"] {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 6px;
  z-index: 3;
  display: flex;
  justify-content: center;
  gap: 12px;
  padding: 0;
}
[data-bz-section="hero-slider"] [data-bz-part~="dots"]:empty { display: none; }
[data-bz-section="hero-slider"] .bz-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #fff;
  opacity: 0.95;
}
[data-bz-section="hero-slider"] .bz-dot[aria-current="true"] { width: 10px; background: var(--accent); }
[data-bz-section="hero-slider"] .bz-dot:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
@media (max-width: 1100px) {
  [data-bz-section="hero-slider"] [data-bz-part~="slide"] > .bz-col:first-child { grid-column: 1 / span 7; }
}
@media (max-width: 640px) {
  [data-bz-section="hero-slider"] [data-bz-part~="slide"] { display: flex; flex-direction: column; min-height: 0; }
  [data-bz-section="hero-slider"] [data-bz-part~="slide"][hidden] { display: none; }
  [data-bz-section="hero-slider"] [data-bz-part~="slide"] > .bz-col:last-child { position: relative; order: -1; width: 100%; aspect-ratio: 4 / 3; }
  [data-bz-section="hero-slider"] [data-bz-part~="slide"] > .bz-col:last-child::after { content: ""; position: absolute; inset: 0; background: linear-gradient(0deg, var(--ink-dark) 0%, rgba(0, 0, 0, 0) 35%); pointer-events: none; }
  [data-bz-section="hero-slider"] [data-bz-part~="slide"] img { object-position: 72% center; }
  [data-bz-section="hero-slider"] [data-bz-part~="slide"] > .bz-col:first-child { padding: 8px 16px 48px; min-height: 250px; }
  [data-bz-section="hero-slider"] h1 { margin-bottom: 16px; }
  [data-bz-section="hero-slider"] .bz-text p { white-space: normal; }
}
